CREATE TABLE public.training_useofforcestandard (
    id bigint NOT NULL,
    exercise character varying(20) NOT NULL,
    age_group character varying(20) NOT NULL,
    minimum integer NOT NULL,
    good integer NOT NULL,
    very_good integer NOT NULL,
    age_sort smallint NOT NULL,
    gender character varying(1) NOT NULL,
    CONSTRAINT training_useofforcestandard_age_sort_check CHECK ((age_sort >= 0))
);


ALTER TABLE public.training_useofforcestandard OWNER TO postgres;

